CREATE TABLE coupon_campaign (id BIGINT NOT NULL AUTO_INCREMENT,code VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(160) NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'draft',starts_at DATETIME(6) NOT NULL,ends_at DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_coupon_campaign_code UNIQUE(code),KEY idx_coupon_campaign_active(status,starts_at,ends_at),CONSTRAINT ck_coupon_campaign_code CHECK(REGEXP_LIKE(code,'^[A-Z0-9-]{3,32}$','c')),CONSTRAINT ck_coupon_campaign_status CHECK(status IN ('draft','active','paused','ended')),CONSTRAINT ck_coupon_campaign_window CHECK(ends_at>starts_at)) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
